use core.process as process

struct Command {
    operation: String
    name: String
    format: String
    dry_run: Bool
}

fn dispatch(command: Command) {
    if command.operation == "list" -> print("list name={command.name} format={command.format} dry_run={command.dry_run}")
    else if command.operation == "inspect" -> print("inspect name={command.name} format={command.format} dry_run={command.dry_run}")
    else if command.operation == "remove" -> print("remove name={command.name} format={command.format} dry_run={command.dry_run}")
    else -> panic("unknown command")
}

fn run() {
    args :: process.argv()
    operation := ""
    name := ""
    format := "text"
    dry_run := false
    i := 1

    loop i < args.len() {
        arg :: args.get(i) ?? panic("missing argument")
        if arg == "--json" {
            format = "json"
        } else if arg == "--dry-run" {
            dry_run = true
        } else if arg == "--format" {
            value :: args.get(i + 1) ?? panic("missing format value")
            if value != "text" && value != "json" -> panic("invalid format")
            format = value
            i = i + 1
        } else if operation.is_empty() {
            if arg == "list" || arg == "ls" -> operation = "list"
            else if arg == "inspect" -> operation = "inspect"
            else if arg == "remove" || arg == "rm" -> operation = "remove"
            else -> panic("unknown command {arg}")
        } else if name.is_empty() {
            name = arg
        } else {
            panic("unexpected argument {arg}")
        }
        i = i + 1
    }

    if operation.is_empty() -> panic("missing command")
    if name.is_empty() -> panic("missing name")
    command :: Command{operation: operation, name: name, format: format, dry_run: dry_run}
    dispatch(command)
}
